head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > removeRowClass]<br/>Body Row 의 인덱스를 사용하여 특정 Body Row 에 설정된 CSS 클래스를 제거합니다.",
    "validation" : [
        "setRowClass() 메소드로 설정한 CSS 클래스만 제거할 수 있습니다.",
        "rowIndex(필수) 파라미터로 CSS 클래스를 제거할 Body Row 의 인덱스를 설정합니다. (0부터, GridView 에 표시된 Row 기준)",
        "className(선택) 파라미터로 Body Row 에서 제거할 CSS 클래스 이름을 공백으로 구분하여 설정합니다.",
        "className 파라미터값을 생략하면 setRowClass() 메소드로 설정한 CSS 클래스를 모두 제거합니다.",
        "removeRowClass() 실행 시 Body Row 의 tr 요소에 설정된 CSS 클래스가 제거됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (col1 ~ col4, 데이터 4행)
scwin.comp_init = async function () {
    // 기존 target/dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="setRowClass(준비) 로 대상 Row 에 cRed cBlue 를 먼저 설정한 뒤 removeRowClass 로 제거합니다. className 을 생략하면 설정된 클래스가 모두 제거됩니다."', '', 'label1');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // GridView 와 바인딩할 DataList 동적 생성 (col1 ~ col4, 데이터 4행)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "col1": "A1", "col2": "B1", "col3": "C1", "col4": "D1" },
        { "col1": "A2", "col2": "B2", "col3": "C2", "col4": "D2" },
        { "col1": "A3", "col2": "B3", "col3": "C3", "col4": "D3" },
        { "col1": "A4", "col2": "B4", "col3": "C4", "col4": "D4" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind"
    };
    let cList = $c.gcm.createCList(properties);

    // Header(col1 ~ col4) + gBody(데이터). 마지막 컬럼 width="*" 로 가로 스크롤 방지
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="바인딩 그리드 (col1 ~ col4, 데이터 4행)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



// setRowClass 실행 (제거 검증 준비) — 대상 Body Row 에 'cRed cBlue' CSS 클래스를 설정
scwin.btn_setRowClass_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());

    // 제거 준비: 해당 Body Row 에 'cRed cBlue' 설정
    target1.setRowClass(rowIndex, "cRed cBlue");
    wf_body_bottom.getObj("scwin").setReturnValue("setRowClass(" + rowIndex + ", cRed cBlue)");

    // getRowClass 로 설정값 확인
    let rtn = target1.getRowClass(rowIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("getRowClass(" + rowIndex + ") : " + rtn);
}



// removeRowClass 실행 — rowIndex 로 Body Row 에 설정된 CSS 클래스 제거
//  - par_className 미설정('') 이면 className 인자를 생략하여 removeRowClass(rowIndex) 호출 -> 전체 제거
//  - 값이 있으면 removeRowClass(rowIndex, className) 호출 (공백구분 일부 제거 포함)
//  - 제거 후 getRowClass + 해당 Row 의 tr 요소 className 실측 (store vs tr 동작 둘 다 출력)
scwin.btn_removeRowClass_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let className = par_className.getValue();

    if (className === "") {
        // className 생략 -> setRowClass 로 설정한 클래스 모두 제거
        target1.removeRowClass(rowIndex);
        wf_body_bottom.getObj("scwin").setReturnValue("removeRowClass(" + rowIndex + ") — className 생략(전체 제거)");
    } else {
        // className 지정 -> 공백구분 일부/전체 제거
        target1.removeRowClass(rowIndex, className);
        wf_body_bottom.getObj("scwin").setReturnValue("removeRowClass(" + rowIndex + ", " + className + ")");
    }

    // getRowClass 로 제거 후 남은 설정값 확인 (전부 제거 시 undefined)
    let rtn = target1.getRowClass(rowIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("getRowClass(" + rowIndex + ") : " + rtn);

    // (@spec) Body Row 의 tr 요소에서 CSS 클래스가 제거되었는지 실측
    let td = document.querySelector("td[id*='target1_cell_" + rowIndex + "_0']");
    if (td && td.parentNode) {
        let tr = td.parentNode;
        wf_body_bottom.getObj("scwin").setReturnValue("대상 Row tr.tagName : " + tr.tagName + " / tr.className : " + tr.className);
    }
}
